const body = $json.body ?? $json;

const cfg = {
  templateDocId: body.config?.templateDocId || 'YOUR_GOOGLE_DOC_TEMPLATE_ID',
  outputDocFolderId: body.config?.outputDocFolderId || 'YOUR_OUTPUT_PDF_FOLDER_ID',
};

function safeText(value) {
  return String(value || '').trim().replace(/[\\/:*?"<>|]/g, '').replace(/\s+/g, ' ');
}

function formatTanggal(value) {
  return String(value || '').trim().replace(/\//g, '-').replace(/\s+/g, ' ');
}

const namaSite = safeText(body.textPlaceholders?.['<<Lokasi Site>>'] || 'SITE');
const kunjunganKe = safeText(body.textPlaceholders?.['<<Keterangan Kunjungan>>'] || 'Kunjungan');
const tanggalKunjungan = formatTanggal(body.textPlaceholders?.['<<Tanggal Kunjungan>>'] || '');

const reportName = safeText(
  body.reportName || `Laporan Visit ${namaSite} ${kunjunganKe} ${tanggalKunjungan}`.trim()
);

const recipientEmail = body.recipientEmail || body.textPlaceholders?.['<<Email>>'] || '';
const textPlaceholders = body.textPlaceholders || {};
const imagePlaceholders = Array.isArray(body.imagePlaceholders) ? body.imagePlaceholders : [];

const cleanImages = imagePlaceholders
  .filter(x => x && x.placeholder)
  .map(x => ({
    placeholder: String(x.placeholder || '').trim(),
    fileId: String(x.fileId || '').trim(),
    publicImageUrl: String(x.publicImageUrl || '').trim(),
  }));

return [{
  json: {
    config: cfg,
    reportName,
    recipientEmail,
    textPlaceholders,
    imagePlaceholders: cleanImages,
    originalPayload: body,
  }
}];

const textPlaceholders = $items('Normalize Payload', 0, 0)[0].json.textPlaceholders || {};
const requests = [];

for (const [placeholder, value] of Object.entries(textPlaceholders)) {
  requests.push({
    replaceAllText: {
      containsText: { text: placeholder, matchCase: true },
      replaceText: value == null ? '' : String(value),
    },
  });
}

return [{
  json: {
    documentId: $json.id,
    docUrl: `https://docs.google.com/document/d/${$json.id}/edit`,
    reportName: $items('Normalize Payload', 0, 0)[0].json.reportName,
    recipientEmail: $items('Normalize Payload', 0, 0)[0].json.recipientEmail,
    imagePlaceholders: $items('Normalize Payload', 0, 0)[0].json.imagePlaceholders,
    requests,
    originalPayload: $items('Normalize Payload', 0, 0)[0].json.originalPayload,
  }
}];

const document = $json;
const base = $items('Build Text Requests', 0, 0)[0].json;
const imagePlaceholders = Array.isArray(base.imagePlaceholders) ? base.imagePlaceholders : [];
const textElements = [];

function scan(elements = []) {
  for (const el of elements) {
    if (el.paragraph?.elements) {
      for (const pe of el.paragraph.elements) {
        const content = pe.textRun?.content || '';
        if (content) {
          textElements.push({
            startIndex: pe.startIndex,
            endIndex: pe.endIndex,
            content,
          });
        }
      }
    }
    if (el.table?.tableRows) {
      for (const row of el.table.tableRows || []) {
        for (const cell of row.tableCells || []) {
          scan(cell.content || []);
        }
      }
    }
    if (el.tableOfContents?.content) {
      scan(el.tableOfContents.content || []);
    }
  }
}

scan(document.body?.content || []);

const allTokens = [];
for (const t of textElements) {
  const regex = /<<[^>]+>>/g;
  let m;
  while ((m = regex.exec(t.content)) !== null) {
    allTokens.push({
      text: m[0],
      startIndex: t.startIndex + m.index,
      endIndex: t.startIndex + m.index + m[0].length,
    });
  }
}

const imageMap = {};
for (const item of imagePlaceholders) {
  if (item?.placeholder) {
    imageMap[item.placeholder] = item.publicImageUrl || '';
  }
}

const requests = [];
allTokens.sort((a, b) => b.startIndex - a.startIndex);

for (const token of allTokens) {
  const imageUrl = imageMap[token.text];

  requests.push({
    deleteContentRange: {
      range: {
        startIndex: token.startIndex,
        endIndex: token.endIndex,
      },
    },
  });

  if (imageUrl) {
    requests.push({
      insertInlineImage: {
        location: { index: token.startIndex },
        uri: imageUrl,
        objectSize: {
          width: { magnitude: 95, unit: 'PT' },
          height: { magnitude: 95, unit: 'PT' },
        },
      },
    });
  }
}

return [{
  json: {
    documentId: base.documentId,
    docUrl: base.docUrl,
    reportName: base.reportName,
    recipientEmail: base.recipientEmail,
    requests,
  },
}];

